1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.time.LocalDate;
13	import java.time.Period;
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
24	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
25	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
26	    @Mapping(target = "checkDigit", expression = "java(formatCheckDigit(owner))")
27	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
29	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
30	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
31	    @Mapping(target = "identityKey", expression = "java(formatIdentityKey(owner))")
32	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
33	    @Mapping(target = "bulkSignupWarning", ignore = true)
34	    @Mapping(target = "possibleDuplicate", expression = "java(owner.getPossibleDuplicateOf() != null)")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /**
38	     * Derives an owner's age band from the birth date, computed against the registration date
39	     * (falling back to the current date when the registration date is absent): {@code MINOR} when
40	     * under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65 or older. Returns
41	     * {@code null} when no birth date is present, so the field is omitted from the response.
42	     */
43	    default OwnerDto.AgeBandEnum formatAgeBand(Owner owner) {
44	        if (owner == null || owner.getBirthDate() == null) {
45	            return null;
46	        }
47	        LocalDate asOf = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
48	        int age = Period.between(owner.getBirthDate(), asOf).getYears();
49	        if (age < 18) {
50	            return OwnerDto.AgeBandEnum.MINOR;
51	        }
52	        if (age < 65) {
53	            return OwnerDto.AgeBandEnum.ADULT;
54	        }
55	        return OwnerDto.AgeBandEnum.SENIOR;
56	    }
57	
58	    /**
59	     * Derives an owner's duplicate-detection identity key as
60	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'} from the stored
61	     * (already E.164-normalized) telephone, lower-cased email and household id. A {@code null}
62	     * telephone, email or household id contributes the empty string in its position.
63	     */
64	    default String formatIdentityKey(Owner owner) {
65	        if (owner == null) {
66	            return null;
67	        }
68	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
69	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase();
70	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
71	        return telephone + "|" + email + "|" + householdId;
72	    }
73	
74	    /**
75	     * Derives an owner's preferred contact channel: {@code EMAIL} when an email address is present
76	     * (non-null and non-blank), otherwise {@code PHONE}.
77	     */
78	    default OwnerDto.ContactPreferenceEnum formatContactPreference(Owner owner) {
79	        if (owner == null) {
80	            return null;
81	        }
82	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
83	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
84	    }
85	
86	    /**
87	     * Derives an owner's locality (region) from the customer-code identity: it is the {@code REGION}
88	     * segment of the {@code '<REGION>-<HASH8>'} customer code (the part before the first {@code '-'}).
89	     * When the customer code is absent it falls back to resolving the region directly, preferring the
90	     * postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and then the fixed city-to-region
91	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), yielding
92	     * {@code "UNKNOWN"} when neither resolves.
93	     */
94	    default String formatLocality(Owner owner) {
95	        if (owner == null) {
96	            return null;
97	        }
98	        String code = owner.getCustomerCode();
99	        if (code != null) {
100	            int dash = code.indexOf('-');
101	            if (dash > 0) {
102	                return code.substring(0, dash);
103	            }
104	        }
105	        String fromPostcode = regionForPostcode(owner.getPostcode());
106	        if (fromPostcode != null) {
107	            return fromPostcode;
108	        }
109	        return switch (owner.getCity() == null ? "" : owner.getCity()) {
110	            case "Sydney" -> "NSW";
111	            case "Melbourne" -> "VIC";
112	            case "Brisbane" -> "QLD";
113	            default -> "UNKNOWN";
114	        };
115	    }
116	
117	    /**
118	     * Resolves a region from a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099,
119	     * QLD 4000-4099). Returns {@code null} when the postcode is absent, not exactly 4 digits, or in
120	     * no known range, signalling that the caller should fall back to the city-to-region table.
121	     */
122	    private String regionForPostcode(String postcode) {
123	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
124	            return null;
125	        }
126	        int value = Integer.parseInt(postcode);
127	        if (value >= 2000 && value <= 2099) {
128	            return "NSW";
129	        }
130	        if (value >= 3000 && value <= 3099) {
131	            return "VIC";
132	        }
133	        if (value >= 4000 && value <= 4099) {
134	            return "QLD";
135	        }
136	        return null;
137	    }
138	
139	    /**
140	     * Computes an owner's membership level, a number from 1 to 4: starting at 1, plus 1 when an email
141	     * is present, plus 1 when the owner's namesake count is 0, plus 1 when the owner's tenure exceeds
142	     * 365 days, capped at 4. Because a newly created owner has zero tenure, a new owner never exceeds
143	     * level 3.
144	     */
145	    default Integer formatMembershipLevel(Owner owner) {
146	        if (owner == null) {
147	            return null;
148	        }
149	        int level = 1;
150	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
151	        if (hasEmail) {
152	            level++;
153	        }
154	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
155	        if (unique) {
156	            level++;
157	        }
158	        boolean tenured = owner.getRegistrationDate() != null
159	            && owner.getRegistrationDate().plusDays(365).isBefore(LocalDate.now());
160	        if (tenured) {
161	            level++;
162	        }
163	        return Math.min(level, 4);
164	    }
165	
166	    /**
167	     * Computes an owner's check digit: a single Luhn check digit (0-9) over the digits contained in the
168	     * customer code. Returns {@code null} when the customer code is absent.
169	     */
170	    default Integer formatCheckDigit(Owner owner) {
171	        if (owner == null || owner.getCustomerCode() == null) {
172	            return null;
173	        }
174	        String code = owner.getCustomerCode();
175	        int sum = 0;
176	        boolean dbl = true;
177	        for (int i = code.length() - 1; i >= 0; i--) {
178	            char c = code.charAt(i);
179	            if (c < '0' || c > '9') {
180	                continue;
181	            }
182	            int d = c - '0';
183	            if (dbl) {
184	                d *= 2;
185	                if (d > 9) {
186	                    d -= 9;
187	                }
188	            }
189	            sum += d;
190	            dbl = !dbl;
191	        }
192	        return (10 - (sum % 10)) % 10;
193	    }
194	
195	    /**
196	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last two
197	     * digits of the registration-date year (e.g. {@code "NSW-1A2B3C4D-M26"}). Returns {@code null} when the
198	     * customer code or registration date is absent.
199	     */
200	    default String formatMembershipNumber(Owner owner) {
201	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
202	            return null;
203	        }
204	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
205	    }
206	
207	    /**
208	     * Formats an owner's stored E.164 telephone for humans as the country code, a space, and the
